<?php
namespace App\Tracking;
use App\Enums\ServerTrackingDispatchStatus; use App\Jobs\DispatchServerTracking; use App\Models\GroundTruthEvent; use App\Models\ServerTrackingDispatch;
class ServerTrackingScheduler { public function __construct(private ServerTrackingEligibility $eligibility){} public function schedule(GroundTruthEvent $e):void { if(!$this->eligibility->allows($e))return; foreach(['ga4','meta'] as $provider){$target=$provider==='ga4'?config('tracking.ga4.server_measurement_id'):config('tracking.meta.pixel_id');$ready=$provider==='ga4'?config('tracking.ga4.server_enabled'):config('tracking.meta.capi_enabled');if(!$ready)continue;$d=ServerTrackingDispatch::firstOrCreate(['ground_truth_event_id'=>$e->id,'provider'=>$provider],['experiment_run_id'=>$e->experiment_run_id,'status'=>ServerTrackingDispatchStatus::Pending,'target_id'=>$target,'api_version'=>$provider==='meta'?config('tracking.meta.graph_api_version'):null,'queued_at'=>now()]);if($d->wasRecentlyCreated)DispatchServerTracking::dispatch($d->id)->onQueue('tracking')->afterCommit();} } }
